37	func TestParseQualifiedHandle(t *testing.T) {
38		t.Parallel()
39		tests := []struct {
40			in           string
41			wantProvider string
42			wantHandle   string
43			wantErr      bool
44		}{
45			{in: "github:alice", wantProvider: "github", wantHandle: "alice"},
46			{in: "github:alice:bob", wantProvider: "github", wantHandle: "alice:bob"}, // only first colon splits
47			{in: "alice", wantErr: true},                                              // no provider prefix
48			{in: "github:", wantErr: true},                                            // empty handle
49			{in: ":alice", wantErr: true},                                             // empty provider
50			{in: "", wantErr: true},
51		}
52		for _, tt := range tests {
53			t.Run(tt.in, func(t *testing.T) {
54				t.Parallel()
55				provider, handle, err := parseQualifiedHandle(tt.in)
56				if tt.wantErr {
57					if err == nil {
58						t.Errorf("parseQualifiedHandle(%q) expected error", tt.in)
59					}
60					return
61				}
62				if err != nil {
63					t.Fatalf("parseQualifiedHandle(%q): %v", tt.in, err)
64				}
65				if provider != tt.wantProvider || handle != tt.wantHandle {
66					t.Errorf("parseQualifiedHandle(%q) = (%q, %q), want (%q, %q)", tt.in, provider, handle, tt.wantProvider, tt.wantHandle)
67				}
68			})
69		}
70	}
