72	func TestPickOrg(t *testing.T) {
73		t.Parallel()
74		orgs := []coreapi.Org{
75			{ID: "01J0ORG0000000000000000001", Name: "acme"},
76			{ID: "01J0ORG0000000000000000002", Name: "globex"},
77		}
78	
79		t.Run("unique match", func(t *testing.T) {
80			t.Parallel()
81			got, err := pickOrg(orgs, "globex")
82			if err != nil {
83				t.Fatalf("pickOrg: %v", err)
84			}
85			if got != "01J0ORG0000000000000000002" {
86				t.Errorf("pickOrg = %q, want globex id", got)
87			}
88		})
89	
90		t.Run("no match", func(t *testing.T) {
91			t.Parallel()
92			if _, err := pickOrg(orgs, "missing"); err == nil {
93				t.Error("pickOrg expected error for unknown name")
94			}
95		})
96	
97		t.Run("ambiguous", func(t *testing.T) {
98			t.Parallel()
99			dupes := []coreapi.Org{
100				{ID: "01J0ORG000000000000000000A", Name: "dup"},
101				{ID: "01J0ORG000000000000000000B", Name: "dup"},
102			}
103			if _, err := pickOrg(dupes, "dup"); err == nil {
104				t.Error("pickOrg expected error for ambiguous name")
105			}
106		})
107	}
