146	func TestFilterProjectsByName(t *testing.T) {
147		t.Parallel()
148		projects := []coreapi.Project{
149			{ID: "1", Name: "a"},
150			{ID: "2", Name: "b"},
151			{ID: "3", Name: "a"},
152		}
153	
154		t.Run("empty name returns all", func(t *testing.T) {
155			t.Parallel()
156			if got := filterProjectsByName(projects, ""); len(got) != 3 {
157				t.Errorf("len = %d, want 3", len(got))
158			}
159		})
160	
161		t.Run("exact filter", func(t *testing.T) {
162			t.Parallel()
163			got := filterProjectsByName(projects, "a")
164			if len(got) != 2 {
165				t.Fatalf("len = %d, want 2", len(got))
166			}
167			for _, p := range got {
168				if p.Name != "a" {
169					t.Errorf("unexpected project %q", p.Name)
170				}
171			}
172		})
173	
174		t.Run("no match", func(t *testing.T) {
175			t.Parallel()
176			if got := filterProjectsByName(projects, "z"); len(got) != 0 {
177				t.Errorf("len = %d, want 0", len(got))
178			}
