// --- Orgs ---

// CreateOrg creates a human-owned org. It rejects any name containing ':',
// which reserves the ':' namespace for system-managed orgs (e.g.
// "entire:system", "gh:<github-org-id>") so a human can never create an org
// whose name collides with one. Trusted callers that need a reserved name use
// CreateOrgWithoutValidation.
func (s *Store) CreateOrg(ctx context.Context, name, region string, ownerAccountID model.AccountID) (*model.Org, error) {
	if strings.ContainsRune(name, ':') {
		return nil, fmt.Errorf("org name %q must not contain ':': %w", name, ErrInvalidName)
	}
	return s.createOrg(ctx, name, region, ownerAccountID)
}

// CreateOrgWithoutValidation creates an org while SKIPPING the ':' check.
//
// DANGER: this is the backdoor that the validated CreateOrg exists to close.
// It is the ONLY way to mint an org in the reserved ':' namespace
// (e.g. serviceaccount.SystemOrgName "entire:system"). Call it ONLY with a
// name your own code constructs — NEVER with a user- or attacker-supplied
// string, or a human can squat a system org name and hijack it.
func (s *Store) CreateOrgWithoutValidation(ctx context.Context, name, region string, ownerAccountID model.AccountID) (*model.Org, error) {
	return s.createOrg(ctx, name, region, ownerAccountID)
}

func (s *Store) createOrg(ctx context.Context, name, region string, ownerAccountID model.AccountID) (*model.Org, error) {
	org := &model.Org{
		ID:     model.NewOrgID(),
		Name:   name,
		Region: region,
	}
	err := s.pool.QueryRow(ctx,
		`INSERT INTO orgs (id, name, region) VALUES ($1, $2, $3) RETURNING created_at`,
		org.ID, org.Name, org.Region,
	).Scan(&org.CreatedAt)
	if err != nil {
		if isUniqueViolation(err) {
			return nil, fmt.Errorf("org name %q: %w", org.Name, ErrNameConflict)
		}
		return nil, fmt.Errorf("insert org: %w", err)
	}

	// Create owner membership (needed for listing orgs by account).
	_, err = s.pool.Exec(ctx,
		`INSERT INTO memberships (id, account_id, org_id, role) VALUES ($1, $2, $3, 'owner')`,
		model.NewMembershipID(), ownerAccountID, org.ID,
	)
	if err != nil {
		return nil, fmt.Errorf("insert owner membership: %w", err)
	}

	// Callback: write authz relations for org ownership.
	if err := s.authz.OrgCreated(ctx, org.ID, ownerAccountID); err != nil {
		return nil, fmt.Errorf("authz org created: %w", err)
	}

	return org, nil
}

