func setupResourceStore(t *testing.T) (resource.Service, authz.Service) {
	t.Helper()

	spiceClient := testutil.SharedSpiceDBClient(t)
	authzSvc := authz.NewStore(spiceClient)
	return setupResourceStoreWithAuthz(t, authzSvc), authzSvc
}

func setupResourceStoreWithAuthz(t *testing.T, authzSvc authz.Service) resource.Service {
	t.Helper()

	// CockroachDB — shared per test binary. Tests use random ULIDs for
	// resources they create, so accumulated data between tests is harmless.
	pool := testutil.SharedMigratedPool(t, "resource",
		testutil.MigrationSet{FS: resmigrations.FS, Table: "goose_resource"},
		// Identity is needed so the account-handle path in FindRepoByOwnerAndName
		// can join on the handles table (no-op when nothing seeds handles, but
		// the table must exist for the query to run).
		testutil.MigrationSet{FS: idmigrations.FS, Table: "goose_identity"},
	)

	return resource.NewStore(pool, authzSvc)
}

