// TestGetOrgByName_CaseInsensitive pins migration 022: org names resolve
// case-insensitively. Org names (unlike projects/repos) are not lowercased at
// create, so this is the one place a mixed-case stored name must still resolve
// from any-case input.
func TestGetOrgByName_CaseInsensitive(t *testing.T) {
	t.Parallel()
	svc, _ := setupResourceStore(t)
	ctx := context.Background()

	suffix := strings.ToLower(model.NewOrgID().String())[18:]
	name := "CaseOrg-" + suffix
	created, err := svc.CreateOrg(ctx, name, "us", model.NewAccountID())
	if err != nil {
		t.Fatalf("create org: %v", err)
	}
	for _, q := range []string{name, strings.ToLower(name), strings.ToUpper(name)} {
		got, err := svc.GetOrgByName(ctx, q)
		if err != nil {
			t.Fatalf("GetOrgByName(%q): %v", q, err)
		}
		if got.ID != created.ID {
			t.Errorf("GetOrgByName(%q) ID = %s, want %s", q, got.ID, created.ID)
		}
	}
}

