// TestListOrgProjects_ByName: the org-scoped list resolves a project by name
// (O(1), case-insensitive), returns 404 for an unknown name, and 404 for a
// project that exists but is owned by a different org.
func TestListOrgProjects_ByName(t *testing.T) {
	t.Parallel()
	e := newCoreEnv(t)

	ownerID, ownerTok := e.user("obn-owner", "gh-obn-owner")
	org, err := e.resource.CreateOrg(e.ctx, "obn-org", "us", ownerID)
	if err != nil {
		t.Fatalf("create org: %v", err)
	}
	proj, err := e.resource.CreateProject(e.ctx, "obn-proj", "org", model.ID(org.ID.String()), "us")
	if err != nil {
		t.Fatalf("create project: %v", err)
	}

	base := "/api/v1/orgs/" + org.ID.String() + "/projects"

	// Exact and case-folded names both resolve to the one project.
	for _, q := range []string{"obn-proj", "OBN-PROJ"} {
		rec := e.get(base+"?name="+q, ownerTok)
		if rec.Code != http.StatusOK {
			t.Fatalf("name=%q status = %d, want 200; body=%s", q, rec.Code, rec.Body.String())
		}
		if b := rec.Body.String(); !strings.Contains(b, proj.ID.String()) {
			t.Errorf("name=%q: project %s missing; body=%s", q, proj.ID, b)
		}
	}

	// Unknown name → 404.
	rec := e.get(base+"?name=obn-missing", ownerTok)
	if rec.Code != http.StatusNotFound {
		t.Fatalf("unknown name status = %d, want 404; body=%s", rec.Code, rec.Body.String())
	}

	// A project owned by a different org is not found under this org, even
	// though project names are globally unique.
	otherOwner, _ := e.user("obn-other", "gh-obn-other")
	otherOrg, err := e.resource.CreateOrg(e.ctx, "obn-other-org", "us", otherOwner)
	if err != nil {
		t.Fatalf("create other org: %v", err)
	}
	if _, err := e.resource.CreateProject(e.ctx, "obn-other-proj", "org", model.ID(otherOrg.ID.String()), "us"); err != nil {
		t.Fatalf("create other project: %v", err)
	}
	rec = e.get(base+"?name=obn-other-proj", ownerTok)
	if rec.Code != http.StatusNotFound {
		t.Fatalf("foreign-project status = %d, want 404; body=%s", rec.Code, rec.Body.String())
	}
}

